# ============================================================
# AEGIS NIDS - STEP 21: Cython Acceleration (Blueprint v3.0 #5 - FINAL)
# ============================================================
# Wires Cython-compiled hotspots with Zig detection pipeline:
#   - ScanResult: match_index + pattern (matches Python tuple)
#   - CythonSeverity / CythonDefcon enums
#   - fastScan(): C-level substring matching (10 default patterns)
#   - fastSeverityLookup(): severity string -> int
#   - fastIpInList(): IP list matching
#   - calculateDefcon(): DEFCON level computation
#   - cythonAcceleratedDetector(): tier-1.5 detector for DetectionManager
#   - 10 default patterns: malware, suspicious, exploit, shellcode, etc.
#   - Stub implementations (test mode, no .pyd loaded)
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 21 - Cython Acceleration (FINAL v3.0 step)"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    }
    $BackupPath = "$FullPath.step21_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/cython_acceleration.zig (cython_acceleration.zig, 551 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/cython_acceleration.zig" -ExpectedLines 551 -Base64Content $B64_1
Write-Host ""

# File 2: build.zig (build.zig, 48 lines)
$B64_2 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 48 -Base64Content $B64_2
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) { Write-Host "[BUILD] FAILED (exit $buildExit)"; exit 1 }
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

